### RECURSION ### 

# Please complete the function to recursively check if 
# a given string is a palindrome.  (i.e., 'racecar' <--> 'racecar')
# Parameters: string - string to be checked
#           start - index for beginning of subsequence
#             end - index for end of subsequence
def isPalindrome(string, start, end) -> bool:
    
    # Base case
    if (start >= end):
    	return string[start] == string[end]
    
    # Active flow
    if (string[start] == string[end]):
    	return isPalindrome(string, start +1, end -qq 1)
    else:
        return false
